/**
 * Camada multilíngue do novo tema Torcisão.
 *
 * Produção: usa o idioma e as relações já existentes no Polylang.
 * Preview/Codespaces: aceita ?lang=en e ?lang=es sem depender do plugin.
 */
function torcisao_current_language(){
    if (function_exists('pll_current_language')) {
        $pll = pll_current_language('slug');
        if (in_array($pll, ['pt','en','es'], true)) return $pll;
    }
    if (isset($_GET['lang'])) {
        $q = sanitize_key(wp_unslash($_GET['lang']));
        if (in_array($q, ['pt','en','es'], true)) return $q;
    }
    $locale = function_exists('determine_locale') ? determine_locale() : get_locale();
    if (stripos($locale, 'en') === 0) return 'en';
    if (stripos($locale, 'es') === 0) return 'es';
    return 'pt';
}

function torcisao_language_locale($lang=null){
    $lang = $lang ?: torcisao_current_language();
    return ['pt'=>'pt-BR','en'=>'en-US','es'=>'es-ES'][$lang] ?? 'pt-BR';
}

function torcisao_current_url_for_lang($lang){
    $lang = in_array($lang, ['pt','en','es'], true) ? $lang : 'pt';
    if (function_exists('pll_the_languages')) {
        $langs = pll_the_languages(['raw'=>1]);
        if (!empty($langs[$lang]['url'])) return $langs[$lang]['url'];
    }
    $scheme = is_ssl() ? 'https' : 'http';
    $host = isset($_SERVER['HTTP_HOST']) ? sanitize_text_field(wp_unslash($_SERVER['HTTP_HOST'])) : parse_url(home_url('/'), PHP_URL_HOST);
    $path = isset($_SERVER['REQUEST_URI']) ? wp_unslash($_SERVER['REQUEST_URI']) : '/';
    $path = strtok($path, '?') ?: '/';
    $url = $scheme.'://'.$host.$path;
    return $lang === 'pt' ? remove_query_arg('lang', $url) : add_query_arg('lang', $lang, $url);
}

function torcisao_page_url($key, $lang=null){
    $lang = $lang ?: torcisao_current_language();
    $base_ids = [
        'home'=>762,
        'blog'=>6,
        'quality'=>18,
        'privacy'=>17,
        'cookies'=>16,
        'arame'=>11,
        'barra'=>7,
        'haste'=>14,
    ];
    if (function_exists('pll_get_post') && isset($base_ids[$key])) {
        $translated = pll_get_post($base_ids[$key], $lang);
        if ($translated) {
            $permalink = get_permalink($translated);
            if ($permalink) return $permalink;
        }
    }
    $paths = [
        'home'=>'/',
        'blog'=>'/blog/',
        'quality'=>'/politicadequalidade/',
        'privacy'=>'/politicadeprivacidade/',
        'cookies'=>'/politicadecookies/',
        'arame'=>'/aramebtc/',
        'barra'=>'/barrabtc/',
        'haste'=>'/hastebc/',
    ];
    $url = home_url($paths[$key] ?? '/');
    return $lang === 'pt' ? $url : add_query_arg('lang', $lang, $url);
}

/** Compatibilidade com os templates de páginas EN/ES já cadastrados no Polylang. */
function torcisao_multilang_template_bridge($template){
    if (!is_page()) return $template;
    $legacy = get_page_template_slug(get_queried_object_id());
    $map = [
        'template-home-en.php'=>'front-page.php','template-home-es.php'=>'front-page.php',
        'home-en.php'=>'page-blog.php','home-es.php'=>'page-blog.php',
        'politicadequalidade-en.php'=>'politicadequalidade.php','politicadequalidade-es.php'=>'politicadequalidade.php',
        'politicadeprivacidade-en.php'=>'politicadeprivacidade.php','politicadeprivacidade-es.php'=>'politicadeprivacidade.php',
        'politicadecookies-en.php'=>'politicadecookies.php','politicadecookies-es.php'=>'politicadecookies.php',
        'aramebtc-en.php'=>'aramebtc.php','aramebtc-es.php'=>'aramebtc.php',
        'aramemtc-en.php'=>'aramemtc.php','aramemtc-es.php'=>'aramemtc.php',
        'arameatc-en.php'=>'arameatc.php','arameatc-es.php'=>'arameatc.php',
        'barrabtc-en.php'=>'barrabtc.php','barrabtc-es.php'=>'barrabtc.php',
        'barramtc-en.php'=>'barramtc.php','barramtc-es.php'=>'barramtc.php',
        'barraatc-en.php'=>'barraatc.php','barraatc-es.php'=>'barraatc.php',
        'barraacoressulfurado-en.php'=>'barraacoressulfurado.php','barraacoressulfurado-es.php'=>'barraacoressulfurado.php',
        'hastebc-en.php'=>'hastebc.php','hastebc-es.php'=>'hastebc.php',
        'hasteac-en.php'=>'hasteac.php','hasteac-es.php'=>'hasteac.php',
    ];
    if (!isset($map[$legacy])) return $template;
    $candidate = get_template_directory().'/'.$map[$legacy];
    return file_exists($candidate) ? $candidate : $template;
}
add_filter('template_include','torcisao_multilang_template_bridge',99);

