function torcisao_i18n_map($lang=null){
    $lang = $lang ?: torcisao_current_language();
    $maps = torcisao_i18n_maps();
    return $maps[$lang] ?? [];
}

function torcisao_translate_string($text, $lang=null){
    $map = torcisao_i18n_map($lang);
    return $map ? strtr((string)$text, $map) : (string)$text;
}

/** Traduz somente nós de texto e atributos de interface, nunca CSS/JS. */
function torcisao_translate_rendered_html($html){
    $lang = torcisao_current_language();
    if ($lang === 'pt' || !$html) return $html;
    $map = torcisao_i18n_map($lang);
    if (!$map) return $html;

    $protected = [];
    $html = preg_replace_callback('#<(script|style)\b[^>]*>.*?</\1>#is', function($m) use (&$protected){
        $token='__TORCISAO_PROTECTED_'.count($protected).'__';
        $protected[$token]=$m[0];
        return $token;
    }, $html);

    $html = preg_replace_callback('/>([^<]+)</u', function($m) use ($map){
        return '>'.strtr($m[1],$map).'<';
    }, $html);

    $html = preg_replace_callback('/\s(aria-label|title|placeholder)=("|\')(.*?)\2/isu', function($m) use ($map){
        return ' '.$m[1].'='.$m[2].strtr($m[3],$map).$m[2];
    }, $html);

    if ($protected) $html = strtr($html, $protected);
    return $html;
}

function torcisao_start_i18n_buffer(){
    if (torcisao_current_language() !== 'pt') ob_start('torcisao_translate_rendered_html');
}
add_action('template_redirect','torcisao_start_i18n_buffer',-999);

function torcisao_language_attributes_filter($output){
    $lang = torcisao_language_locale();
    $output = preg_replace('/lang=("|\')[^"\']*("|\')/i', 'lang="'.esc_attr($lang).'"', $output);
    return $output;
}
add_filter('language_attributes','torcisao_language_attributes_filter',20);

function torcisao_i18n_body_classes($classes){
    $classes[]='tor-lang-'.torcisao_current_language();
    return $classes;
}
add_filter('body_class','torcisao_i18n_body_classes');
